"use client";

import useSWR from "swr";
import { Card, CardContent } from "@/components/ui/card";
import { Users, Wifi, Server } from "lucide-react";

const fetcher = (url: string) => fetch(url).then((res) => res.json());

interface ServerCardProps {
    name: string;
    ip: string;
    color: "cyan" | "purple";
}

export default function ServerCard({ name, ip, color }: ServerCardProps) {
    const { data, error, isLoading } = useSWR(`/api/status?server=${ip}`, fetcher, {
        refreshInterval: 15000, // Refresh every 15s
    });

    const isOnline = data?.online;
    const colorClasses =
        color === "cyan"
            ? "text-cyan-400 bg-cyan-500/10 border-cyan-500/20"
            : "text-purple-400 bg-purple-500/10 border-purple-500/20";

    return (
        <Card className="relative overflow-hidden border-white/5 bg-black/40 backdrop-blur-md">
            {/* Decorative Glow */}
            <div className={`absolute -top-24 -right-24 h-48 w-48 rounded-full blur-3xl opacity-20 bg-${color}-500`} />

            <CardContent className="p-6">
                <div className="flex justify-between items-start mb-6">
                    <div>
                        <h2 className="text-2xl font-bold text-white tracking-tight">{name}</h2>
                        <p className="text-sm text-neutral-400 mt-1 font-mono">{ip}</p>
                    </div>
                    <div className={`px-3 py-1 rounded-full border flex items-center gap-2 text-sm font-medium ${isOnline ? "text-emerald-400 border-emerald-500/20 bg-emerald-500/10" :
                        isLoading ? "text-neutral-400 border-neutral-500/20 bg-neutral-500/10" :
                            "text-red-400 border-red-500/20 bg-red-500/10"
                        }`}>
                        <span className="relative flex h-2 w-2">
                            {isOnline && <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>}
                            <span className={`relative inline-flex rounded-full h-2 w-2 ${isOnline ? 'bg-emerald-500' : isLoading ? 'bg-neutral-500' : 'bg-red-500'}`}></span>
                        </span>
                        {isOnline ? "Online" : isLoading ? "Pinging..." : "Offline"}
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className={`p-4 rounded-lg flex flex-col gap-1 border ${colorClasses}`}>
                        <div className="flex items-center gap-2 text-sm opacity-80">
                            <Users className="w-4 h-4" />
                            Players
                        </div>
                        <div className="text-2xl font-bold">
                            {isLoading ? (
                                <div className="h-8 w-16 bg-white/10 rounded animate-pulse" />
                            ) : (
                                <span>{data?.players || 0} <span className="text-sm font-normal opacity-50">/ {data?.maxPlayers || 0}</span></span>
                            )}
                        </div>
                    </div>

                    <div className="p-4 rounded-lg flex flex-col gap-1 border border-white/5 bg-white/5">
                        <div className="flex items-center gap-2 text-sm text-neutral-400">
                            <Wifi className="w-4 h-4" />
                            Ping
                        </div>
                        <div className="text-2xl font-bold text-white">
                            {isLoading ? (
                                <div className="h-8 w-12 bg-white/10 rounded animate-pulse" />
                            ) : (
                                <span>{data?.ping !== -1 && data?.ping !== undefined ? `${data?.ping}ms` : '---'}</span>
                            )}
                        </div>
                    </div>

                    <div className="col-span-2 p-4 rounded-lg flex flex-col gap-1 border border-white/5 bg-white/5">
                        <div className="flex items-center gap-2 text-sm text-neutral-400">
                            <Server className="w-4 h-4" />
                            Version
                        </div>
                        <div className="text-lg font-medium text-white truncate">
                            {isLoading ? (
                                <div className="h-6 w-32 bg-white/10 rounded animate-pulse" />
                            ) : (
                                data?.version || 'Unknown'
                            )}
                        </div>
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}
